import { NextResponse } from "next/server";
import { createSupabaseServer } from "@/lib/supabase/server";
import { API_BASE } from "@/lib/api";
import { MFA_COOKIE, mfaCookieOptions, signMfaCookie } from "@/lib/mfa-cookie";

/**
 * Completes enrolment from the gate screen: confirms a code generated by the
 * new secret, then issues the marker cookie so the user lands in the app with
 * two-factor authentication switched ON rather than skipped.
 *
 * Minting here is not a shortcut past the gate — entering a code from the
 * authenticator they just paired IS the second factor. The backend refuses this
 * call outright for an account that already has 2FA enabled, so a stolen session
 * cannot use it to swap in an attacker's device.
 */
export async function POST(request: Request) {
  const supabase = await createSupabaseServer();

  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    return NextResponse.json({ error: "Niste prijavljeni." }, { status: 401 });
  }

  const {
    data: { session },
  } = await supabase.auth.getSession();

  if (!session) {
    return NextResponse.json({ error: "Sesija je istekla." }, { status: 401 });
  }

  let secret: string;
  let token: string;
  try {
    const body = await request.json();
    secret = String(body?.secret ?? "").trim();
    token = String(body?.token ?? "").trim();
  } catch {
    return NextResponse.json({ error: "Neispravan zahtjev." }, { status: 400 });
  }

  if (!secret || !token) {
    return NextResponse.json({ error: "Nedostaje kod ili tajni ključ." }, { status: 400 });
  }

  let backendResponse: Response;
  try {
    backendResponse = await fetch(`${API_BASE}/api/2fa/verify-setup`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${session.access_token}`,
      },
      body: JSON.stringify({ secret, token }),
      cache: "no-store",
    });
  } catch {
    return NextResponse.json(
      { error: "Poslužitelj nije dostupan. Pokušajte ponovo." },
      { status: 503 },
    );
  }

  const result = await backendResponse.json().catch(() => null);

  if (!backendResponse.ok || result?.success !== true) {
    // The backend's message is passed through here, unlike on the login gate:
    // during enrolment the distinctions are real and actionable ("wrong code",
    // "clock is off", "already enabled"), not a hint to an attacker.
    return NextResponse.json(
      { error: result?.message ?? result?.error ?? "Aktivacija nije uspjela." },
      { status: backendResponse.status === 503 ? 503 : 400 },
    );
  }

  const response = NextResponse.json({
    success: true,
    recovery_codes: result?.recovery_codes ?? [],
  });

  response.cookies.set(MFA_COOKIE, await signMfaCookie(user.id), mfaCookieOptions());

  return response;
}
